// 蜡笔漫画（labimanhua.com）漫画源插件 —— MiaoQi / Breeze 协议
// 图片数据 AES-128-CBC 加密（key 硬编码自站点 cms.min.js）：
//   params base64 解码 -> 前 16 字节 IV + 密文 -> AES 解密 -> JSON
//     { chapter_images, images_hosts, ... }
// 图片 URL = images_hosts[0] + "/" + chapter_images[i]

const BASE = 'https://www.labimanhua.com';
const REFERER = 'https://www.labimanhua.com/';
const UA =
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';

const UUID = 'a7e9c2f4-6d81-4b3a-9e5c-8f2d1a0b6c4e';
const AES_KEY = '5V&RoR%Jf@pJPydF';

// crypto-js 4.1.1（base64 内嵌，避免转义问题）
const CRYPTO_JS_B64 = '';

let cryptoReady = false;
function ensureCrypto() {
  if (cryptoReady) return;
  const src = Buffer.from(CRYPTO_JS_B64, 'base64').toString();
  (0, eval)(src);
  cryptoReady = true;
}

function headers(extra) {
  const h = { 'User-Agent': UA, 'Referer': REFERER };
  if (extra) {
    for (const k in extra) h[k] = extra[k];
  }
  return h;
}

async function getText(url, extraHeaders) {
  const res = await fetch(url, { headers: headers(extraHeaders) });
  if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + url);
  return await res.text();
}

function clean(s) {
  return String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
}

// 章节列表缓存：comicId -> eps
const epsCache = {};

function decryptParams(params) {
  ensureCrypto();
  const raw = CryptoJS.enc.Base64.parse(params);
  const iv = CryptoJS.lib.WordArray.create(raw.words.slice(0, 4), 16);
  const cipher = CryptoJS.lib.WordArray.create(raw.words.slice(4));
  const dec = CryptoJS.AES.decrypt(
    { ciphertext: cipher },
    CryptoJS.enc.Utf8.parse(AES_KEY),
    { iv: iv },
  );
  return JSON.parse(dec.toString(CryptoJS.enc.Utf8));
}

async function getInfo() {
  return {
    name: '蜡笔漫画',
    uuid: UUID,
    version: '1.0.0',
    describe: 'labimanhua.com 蜡笔漫画源：搜索、详情、阅读',
    iconUrl: '',
    home: 'https://www.labimanhua.com/',
  };
}

async function searchComic(args) {
  const keyword = String(args.keyword || '');
  const url = BASE + '/search?q=' + encodeURIComponent(keyword);
  const html = await getText(url);
  const $ = globalThis.BreezeHtml.load(html);
  const items = [];
  $('li a[href^="/"]').each(function () {
    const href = $(this).attr('href') || '';
    if (href.indexOf('/category') === 0 || href.indexOf('/ranking') === 0 ||
        href.indexOf('/update') === 0 || href === '/' ||
        href.indexOf('/search') === 0) return;
    if (href.indexOf('.html') >= 0) return; // 章节链接
    const img = $(this).find('img').first();
    const src = img.attr('src') || '';
    if (!src) return;
    const title = clean(img.attr('alt') || $(this).attr('title') || '');
    if (!title) return;
    items.push({
      source: UUID,
      id: href,
      title: title,
      subtitle: clean($(this).find('p').last().text()),
      cover: { url: src },
    });
  });
  return { items: items, paging: { hasReachedMax: true } };
}

async function fetchDetail(comicId) {
  const url = comicId.indexOf('http') === 0 ? comicId : BASE + comicId;
  const html = await getText(url);
  const $ = globalThis.BreezeHtml.load(html);

  const title = clean($('article h1').first().text());
  const cover = $('figure img').first().attr('src') || '';
  const author = (html.match(/<strong>作者:<\/strong>\s*([^<]{1,40})/) || [])[1] || '';
  const status = (html.match(/<strong>状态:<\/strong>\s*([^<]{1,40})/) || [])[1] || '';

  const eps = [];
  $('#chapter-grid li a[href^="/"]').each(function () {
    const href = $(this).attr('href') || '';
    const m = href.match(/\/([A-Za-z0-9]{6,14})\.html$/);
    if (!m) return;
    const name = clean($(this).text());
    if (!name) return;
    eps.push({ id: m[1], name: name, order: eps.length });
  });

  const metadata = [];
  if (author) metadata.push({ name: '作者', value: [{ name: author }] });
  if (status) metadata.push({ name: '状态', value: [{ name: status }] });

  return {
    source: UUID,
    comicId: comicId,
    data: {
      normal: {
        comicInfo: {
          title: title,
          creator: { name: author },
          description: '',
          cover: { url: cover },
          metadata: metadata,
          extern: { status: status === '已完结' ? 'completed' : 'ongoing' },
        },
        eps: eps,
      },
    },
  };
}

async function getComicDetail(args) {
  const comicId = String(args.comicId || '');
  const detail = await fetchDetail(comicId);
  epsCache[comicId] = detail.data.normal.eps;
  return detail;
}

async function getChapter(args) {
  const comicId = String(args.comicId || '');
  const chapterId = String(args.chapterId || '');
  const url = comicId.indexOf('http') === 0
    ? comicId + '/' + chapterId + '.html'
    : BASE + comicId + '/' + chapterId + '.html';
  const html = await getText(url);

  const pages = [];
  const m = html.match(/params\s*=\s*'([^']+)'/);
  if (m) {
    try {
      const data = decryptParams(m[1]);
      const host = data.images_hosts && data.images_hosts.length
        ? data.images_hosts[0]
        : '';
      const imgs = data.chapter_images || [];
      for (let i = 0; i < imgs.length; i++) {
        const p = imgs[i];
        if (!p) continue;
        const imgUrl = /^https?:\/\//.test(p) ? p : host + '/' + p;
        pages.push({
          id: String(i + 1),
          name: String(i + 1),
          path: '',
          url: imgUrl,
        });
      }
      // 学习图片域名 headers
      if (pages.length > 0) {
        try {
          await fetch(pages[0].url, { headers: headers() });
        } catch (e) {}
      }
    } catch (e) {}
  }

  // 章节列表：优先缓存，miss 时抓详情页
  let eps = epsCache[comicId];
  if (!eps) {
    try {
      const detail = await fetchDetail(comicId);
      eps = detail.data.normal.eps;
      epsCache[comicId] = eps;
    } catch (e) {
      eps = [];
    }
  }

  let chapterName = '';
  for (const c of eps) {
    if (c.id === chapterId) {
      chapterName = c.name;
      break;
    }
  }
  if (!chapterName) chapterName = '第' + chapterId + '话';

  return {
    comicId: comicId,
    data: {
      comic: { id: comicId, title: '' },
      chapter: { id: chapterId, name: chapterName, pages: pages },
      chapters: eps,
    },
  };
}

async function fetchImageBytes(args) {
  const url = String(args.url || '');
  const res = await fetch(url, { headers: headers() });
  if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + url);
  const buf = await res.arrayBuffer();
  return new Uint8Array(buf);
}

module.exports = {
  getInfo,
  searchComic,
  getComicDetail,
  getChapter,
  fetchImageBytes,
};
